@push('scripts')<script>
$(function(){
 const canCreate=@json(auth()->user()->can('sewing.create')), canUpdate=@json(auth()->user()->can('sewing.update')), canManage=canCreate||canUpdate, modalEl=document.getElementById('sewingModal'), modal=modalEl?new bootstrap.Modal(modalEl):null, moModal=canManage?new bootstrap.Modal(document.getElementById('sewingMoModal')):null, materialModal=canManage?new bootstrap.Modal(document.getElementById('sewingMaterialModal')):null;
 const table=$('#sewingTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:{url:@json(route('super.sewing.dt')),data:d=>{d.from_date=$('#sewingFrom').val();d.to_date=$('#sewingTo').val()}},columns:[{data:'DT_RowIndex',orderable:false,searchable:false},{data:'actions',orderable:false,searchable:false,className:'text-nowrap'},{data:'number',name:'sewing_number'},{data:'date',name:'processed_at',render:d=>d?new Date(d+'T00:00:00').toLocaleDateString():''},{data:'mo',name:'productionOrder.number'}],order:[[3,'desc']],drawCallback:()=>window.feather&&feather.replace()});
 function safe(v){return $('<div>').text(v??'—').html()}
 function detailMarkup(d){return `<div class="p-3 bg-light-subtle"><div class="table-responsive"><table class="table table-sm table-bordered bg-white mb-0"><thead><tr><th>{{ __('ui.sewing.style') }}</th><th>{{ __('ui.sewing.product_code') }}</th><th>{{ __('ui.sewing.product_name') }}</th><th>{{ __('ui.sewing.cutting_reception') }}</th><th>{{ __('ui.sewing.quantity') }}</th><th>{{ __('ui.sewing.rejected') }}</th><th>{{ __('ui.sewing.send_to_packing') }}</th><th>{{ __('ui.sewing.po_buyer') }}</th><th>{{ __('ui.sewing.mo') }}</th><th>{{ __('ui.sewing.material_code') }}</th><th>{{ __('ui.sewing.material_name') }}</th><th>{{ __('ui.sewing.material_unit') }}</th><th>{{ __('ui.sewing.material_waste') }}</th></tr></thead><tbody><tr><td>${safe(d.style)}</td><td>${safe(d.product_code)}</td><td>${safe(d.product_name)}</td><td class="text-end">${safe(d.cutting_reception)}</td><td class="text-end">${safe(d.input_quantity)}</td><td class="text-end">${safe(d.rejected_quantity)}</td><td class="text-end">${safe(d.good_quantity)}</td><td>${safe(d.po_buyer)}</td><td>${safe(d.mo)}</td><td>${safe(d.material_code)}</td><td>${safe(d.material_name)}</td><td>${safe(d.material_unit)}</td><td class="text-end">${safe(d.material_waste_quantity)}</td></tr></tbody></table></div></div>`}
 $('#sewingTable').on('click','.btn-show-sewing-detail',function(){const tr=$(this).closest('tr'),row=table.row(tr);if(row.child.isShown()){row.child.hide();tr.removeClass('shown');$(this).text(@json(__('ui.common.view_detail')))}else{row.child(detailMarkup(row.data())).show();tr.addClass('shown');$(this).text(@json(__('ui.common.close')))}});
 if(canManage){
  const moTable=canCreate?$('#sewingMoTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:@json(route('super.sewing.production-orders.dt')),columns:[{data:'number',name:'number'},{data:'buyer_po_number',name:'buyer_po_number'},{data:'style',orderable:false,searchable:false},{data:'product_code',orderable:false,searchable:false},{data:'product_name',orderable:false,searchable:false},{data:'available_cutting_quantity',className:'text-end'},{data:'actions',orderable:false,searchable:false}]}):null;
  const materialTable=$('#sewingMaterialTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:{url:@json(route('super.sewing.materials.dt')),data:d=>d.production_order_id=$('#sewingMoId').val()},columns:[{data:'code'},{data:'name'},{data:'unit',orderable:false,searchable:false},{data:'actions',orderable:false,searchable:false}]});
  const reset=()=>{$('#sewingForm')[0].reset();$('#sewingEntryId,#sewingMoId,#sewingMaterialId').val('');$('#sewingDate').val(@json(now()->toDateString()));$('#sewingNumber,#sewingMoLabel,#sewingProduct,#sewingStyle,#sewingPoBuyer,#sewingUnit,#sewingAvailable,#sewingMaterialLabel,#sewingMaterialUnit').val('');$('#sewingReject,#sewingWaste').val(0);$('#saveSewing').html('<i data-feather="save" class="icon-sm me-1"></i>'+@json(__('ui.common.save')));if(canCreate)$.get(@json(route('super.sewing.number-preview'))).done(r=>$('#sewingNumber').val(r.number));};
  if(canCreate){$('#addSewing').on('click',()=>{reset();modal.show()});$('#chooseSewingMo').on('click',()=>{modal.hide();moTable.ajax.reload();moModal.show()})}
  if(canCreate)$(document).on('click','.btn-select-sewing-mo',function(){const b=$(this);$('#sewingMoId').val(b.data('id'));$('#sewingMoLabel').val(b.data('number'));$('#sewingProduct').val(b.data('product'));$('#sewingStyle').val(b.data('style'));$('#sewingPoBuyer').val(b.data('po'));$('#sewingUnit').val(b.data('unit'));$('#sewingAvailable').val(b.data('available'));$('#sewingQty').attr('max',b.data('available'));moModal.hide();modal.show();materialTable.ajax.reload()});
  $('#chooseSewingMaterial').on('click',()=>{if(!$('#sewingMoId').val())return;modal.hide();materialTable.ajax.reload();materialModal.show()});$(document).on('click','.btn-select-sewing-material',function(){let b=$(this);$('#sewingMaterialId').val(b.data('id'));$('#sewingMaterialLabel').val(b.data('label'));$('#sewingMaterialUnit').val(b.data('unit'));materialModal.hide();modal.show()});
  $('#sewingForm').on('submit',function(e){e.preventDefault();const id=$('#sewingEntryId').val(),url=id?@json(route('super.sewing.update',['entry'=>'__ID__'])).replace('__ID__',id):@json(route('super.sewing.store'));$.ajax({url,method:id?'PUT':'POST',data:$(this).serialize()}).done(r=>{modal.hide();table.ajax.reload(null,false);Swal.fire({icon:'success',title:@json(__('ui.workflow.success')),text:r.message})}).fail(x=>Swal.fire({icon:'error',title:@json(__('ui.workflow.failure')),text:Object.values(x.responseJSON?.errors||{}).flat().join('\n')||x.responseJSON?.message||'Error'}))});
  $(document).on('click','.btn-edit-sewing',function(){const b=$(this);reset();$('#sewingEntryId').val(b.data('id'));$('#sewingMoId').val(b.data('mo'));$('#sewingMoLabel').val(b.data('mo-number'));$('#sewingProduct').val(b.data('product'));$('#sewingStyle').val(b.data('style'));$('#sewingPoBuyer').val(b.data('po'));$('#sewingUnit').val(b.data('unit'));$('#sewingDate').val(b.data('date'));$('#sewingQty').val(b.data('input'));$('#sewingPacking').val(b.data('good'));$('#sewingReject').val(b.data('reject'));$('#sewingMaterialId').val(b.data('material'));$('#sewingMaterialLabel').val(b.data('material-label'));$('#sewingMaterialUnit').val(b.data('material-unit'));$('#sewingWaste').val(b.data('waste'));$('#sewingNumber').val(b.data('number'));$('#sewingAvailable').val('');$('#saveSewing').text(@json(__('ui.common.save_changes')));modal.show()});
 }
 $(document).on('click','.btn-delete-sewing',function(){const id=$(this).data('id');Swal.fire({icon:'warning',title:@json(__('ui.common.confirm_delete')),showCancelButton:true,confirmButtonText:@json(__('ui.common.delete')),cancelButtonText:@json(__('ui.common.cancel'))}).then(x=>{if(x.isConfirmed)$.ajax({url:@json(route('super.sewing.destroy',['entry'=>'__ID__'])).replace('__ID__',id),method:'DELETE',data:{_token:@json(csrf_token())}}).done(r=>{table.ajax.reload(null,false);Swal.fire({icon:'success',text:r.message})}).fail(x=>Swal.fire({icon:'error',text:Object.values(x.responseJSON?.errors||{}).flat().join('\n')||x.responseJSON?.message||'Error'}))})});
 $('#sewingFilter').on('click',()=>table.ajax.reload());$('#sewingExport').on('click',function(e){e.preventDefault();const q=new URLSearchParams();if($('#sewingFrom').val())q.set('from_date',$('#sewingFrom').val());if($('#sewingTo').val())q.set('to_date',$('#sewingTo').val());location.href=this.href+'?'+q.toString()});
});
</script>@endpush
